// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(address player, uint8 playCount) public {
        vm.assume(player != address(0));
        vm.assume(player != address(c));
        playCount = uint8(bound(playCount, 1, 10));

        uint256 totalCollected = 0;
        for (uint8 i = 0; i < playCount; i++) {
            uint256 ticket = 10;
            vm.deal(player, ticket);
            vm.prank(player);
            c.play{value: ticket}();
            totalCollected += ticket;
        }

        uint256 paid = 0;
        paid += address(c.bank()).balance;
        paid += address(c).balance;
        paid += address(player).balance;
        paid += c.pot();

        assertTrue(paid >= totalCollected);
    }
}
